+++ b/src/io/sales-import.js
@@ -0,0 +1,32 @@
+import { AppError } from "../errors.js";
+import { importSales } from "../domain/sales.js";
+
+/** Parses sales CSV with physical row numbers and imports the complete file. */
+export function importSalesCsv(store, text) {
+  if (typeof text !== "string") throw new AppError("bad_request", { reason: "csv must be text" });
+  const rows = [];
+  let header;
+  const lines = text.split(/\r?\n/);
+  for (let i = 0; i < lines.length; i++) {
+    if (!lines[i].trim()) continue;
+    const fields = [];
+    let rest = lines[i];
+    while (true) {
+      const match = /^(?:"((?:[^"]|"")*)"|([^",]*))(,|$)/.exec(rest);
+      if (!match) throw new AppError("bad_request", { reason: `row ${i + 1}: invalid CSV` });
+      fields.push((match[1] === undefined ? match[2] : match[1].replace(/""/g, '"')).trim());
+      rest = rest.slice(match[0].length);
+      if (!match[3]) break;
+    }
+    if (!header) {
+      header = fields;
+      if (header.length !== 4 || new Set(header).size !== 4 || !["ticket", "soldAt", "dishId", "qty"].every((key) => header.includes(key)))
+        throw new AppError("bad_request", { reason: `row ${i + 1}: expected columns ticket,soldAt,dishId,qty` });
+    } else {
+      if (fields.length !== header.length) throw new AppError("bad_request", { reason: `row ${i + 1}: wrong column count` });
+      rows.push({ ...Object.fromEntries(header.map((key, j) => [key, fields[j]])), row: i + 1 });
+    }
+  }
+  if (!header) throw new AppError("bad_request", { reason: "row 1: missing header" });
+  return importSales(store, rows);
+}
